  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Orientin, a luteolin C-glucoside with the same catechol B-ring and glucose moiety, showed only low brain levels after i.v. administration in rats, attributed to high polarity; this is the closest negative analogue but differs in the C-glycosidic linkage.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Quercetin 3-O-glucoside, a flavonoid O-glucoside with the same glucose and catechol B-ring, was detected in rat brain after oral administration, demonstrating that O-glucosylated flavonoids can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Camellianin B, an apigenin 7-O-glycoside, was detected in rat brain after intragastric administration, directly supporting brain access for a 7-O-glycosyl flavone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Astragalin, a kaempferol 3-O-glucoside, transferred across the blood-brain barrier in rat tissue distribution studies.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Isovitexin, a C-glucosyl flavone, was quantified in rat brain and cerebellum after i.v. administration, showing measurable brain penetration despite a glycosyl substituent.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query is a luteolin 7-O-glucoside; although the closest C-glucoside analogue (orientin) showed poor brain penetration, multiple O-glucosylated flavonoids—including quercetin 3-O-glucoside, astragalin, camellianin B, and isovitexin—were detected in brain after systemic administration, and the O-glycosidic linkage of the query aligns with these permeable analogues.",
  "evidence_gaps": [
    "No direct experimental record for luteolin 7-O-glucoside itself; prediction relies on close flavonoid glycoside analogues.",
    "Most supportive records report qualitative detection in brain rather than quantitative unbound brain-to-plasma ratios.",
    "Potential species/route differences and efflux-transporter involvement are not fully resolved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

